    def __init__(self):
        self._template = None
        self._variables = {}

    @classmethod
    def from_string(cls, template_str):
        return cls().set_template(template_str)

    def set_template(self, template_str):
        self._template = template_str
        return self

    def render(self, **kwargs):
        if not self._template:
            raise ValueError("Template has not been set")

        # Replace variables in the template
        for key, value in kwargs.items():
            self._variables[key] = value

        # Parse the template and replace placeholders with actual values
        rendered = self._parse_template()

        return rendered

    def _parse_template(self):
        # Split the template into blocks and placeholders
        blocks = self._split_blocks()

        # Process each block
        for block in blocks:
            block = self._process_block(block)

            # Add processed block back to the template
            self._template = self._replace_placeholder(self._template, block)

        return self._template

    def _split_blocks(self):
        # Use regular expression to split the template into blocks and placeholders
        pattern = r"{{ (.*?) }}|\n"
        return re.split(pattern, self._template)

    def _process_block(self, block):
        # Check if the block contains variables or conditional statements
        if "{{" in block:
            # Process variables
            return self._process_variables(block)
        elif "if" in block:
            # Process conditional statements
            return self._process_conditional(block)
        else:
            # Return the block as it is if no changes were made
            return block

    def _process_variables(self, block):
        # Replace variables with their corresponding values
        for var in re.findall(r"\{\{ (\w+) \}\}", block):
            if var in self._variables:
                block = block.replace(f"{{ {var} }}", str(self._variables[var]))
            else:
                raise ValueError(f"Variable '{var}' not found in the template")

        return block

    def _process_conditional(self, block):
        # Check if the block contains an if statement
        match = re.search(r"if\s+([\w\s]+)\s*:\s*(.+)", block)
        if match:
            condition = match.group(1)
            content = match.group(2)

            # Evaluate the condition
            if eval(condition):
                # Render the content if the condition is true
                content = self._render(content)
            else:
                # Render nothing if the condition is false
                content = ""

            block = block.replace(match.group(0), content)
        else:
            # Return the block as it is if no changes were made
            return block

# Example usage
