        # Add a new key-value pair to the dictionary
        if key in self.data:
            self.data[key].append(value)
        else:
            self.data[key] = [value]

    def get(self, key):
        # Retrieve all values associated with a given key
        return self.data.get(key, [])

    def keys(self):
        # Return all unique keys in the dictionary
        return set(self.data.keys())

    def values(self):
        # Return all values in the dictionary
        return set([value for sublist in self.data.values() for value in sublist])

