    def match(self, compiled_pattern, string):
        # Match the entire string against the compiled pattern
        match = compiled_pattern.match(string)
        if match:
            return True
        return False

    def fullmatch(self, compiled_pattern, string):
        # Check if the entire string matches the compiled pattern
        match = compiled_pattern.fullmatch(string)
